// Illustrative: an event message is a kind of message, not an operator; this only maps the flow onto RxJS, and the copying and the age check belong to other patterns.
interface Transition {
  readonly order: number;
  readonly phase: string;
  // the event's time, most of what it says
  readonly at: number;
}

// the channel the lifecycle announces on, naming no reader
const transitions$ = new Subject<Transition>();
// the event message, sent as the change happens
const announce = (transition: Transition) => transitions$.next(transition);

// a subscriber decides for itself what the news means
transitions$.subscribe((transition) => quality.note(transition));
// another subscriber decides differently
transitions$.subscribe((transition) => intent.expect(transition));

// the beacon: replays the last announcement it was given, however old
const beacon$ = new ReplaySubject<Transition>(1);
// the beacon write, one more subscriber to the announcements
transitions$.subscribe((transition) => beacon$.next(transition));

const sweep = (now: number) =>
  beacon$.pipe(
    // the sweep reads whatever the beacon holds now
    take(1),
    // the age check: the reader judges expiry by its own clock
    map(({ at }) => (now - at >= staleAfter ? 'stale' : 'fresh')),
  );
